import { ContainerPropertiesSchema } from '@pmndrs/uikit';
import { componentDefaults, Container, } from '@pmndrs/uikit';
import { computed } from '@preact/signals-core';
import { Button } from './index.js';
export const ButtonIconPropertiesSchema = ContainerPropertiesSchema;
export class ButtonIcon extends Container {
    constructor(inputProperties, initialClasses, config) {
        const size = computed(() => {
            const btn = this.parentContainer.value;
            if (!(btn instanceof Button)) {
                return 24;
            }
            const size = btn.properties.value.size ?? 'lg';
            if (size === 'lg') {
                return 24;
            }
            return 16;
        });
        super(inputProperties, initialClasses, {
            defaults: componentDefaults,
            ...config,
            defaultOverrides: {
                '*': {
                    width: size,
                    height: size,
                },
                ...config?.defaultOverrides,
            },
        });
    }
}
